tool_input.command:
cd src/pages && sed -i 's#<span className="bullet" style={{ background: .var(--tone). }} />#<span className="bullet bullet--tone" />#' ProductsPage.tsx && sed -i "s#^import ProductImage from '../components/ProductImage';#import ProductImage from '../components/ProductImage';
import { CategoryIcon } from '../components/Icons';
import { Marker, PixelStage, Vignette } from '../components/Pixel';
import { scenes } from '../art/scenes';#; s#import { categories, categoryLabel, formatPrice, products,#import { categories, categoryLabel, FREE_SHIPPING_THRESHOLD, formatPrice, products,#" ProductsPage.tsx && grep -n "bullet\|^import" ProductsPage.tsx

cd src/pages && node -e "
const fs=require('fs');let s=fs.readFileSync('CartPage.tsx','utf8');
for (const f of ['name','email','address']) {
  s=s.replace('className=\"input'+(f==='address'?' textarea':'')+'\"\n                  '+(f==='address'?'rows':'autoComplete'), (m)=>m.replace('className=\"input'+(f==='address'?' textarea':'')+'\"', 'className={\x60input'+(f==='address'?' textarea':'')+' \${nudgeClass(\''+f+'\')}\x60}'));
  s=s.replace('data-testid=\"error-'+f+'\">\n                    {errors.'+f+'}', 'data-testid=\"error-'+f+'\" role=\"alert\">\n                    <AlertIcon />\n                    {errors.'+f+'}');
}
s=s.replace('<button type=\"submit\" className=\"button button-primary\" data-testid=\"place-order\">','<button type=\"submit\" className=\"btn-gold\" data-testid=\"place-order\">');
s=s.replace('            </form>\n          </section>','            </form>\n            </div>\n          </section>');
fs.writeFileSync('CartPage.tsx',s);"
grep -n "nudgeClass\|AlertIcon\|btn-gold\|</div>$" CartPage.tsx | head -20
